CREATE OR REPLACE FUNCTION public.reader_joint_action(p_action text,p_club uuid DEFAULT NULL,p_reading uuid DEFAULT NULL,p_book uuid DEFAULT NULL,p_chapters integer DEFAULT 1,p_goal text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE b public.books; r public.reader_joint_readings; result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión.'; END IF; IF p_action='create' THEN IF NOT EXISTS(SELECT 1 FROM public.reader_clubs WHERE id=p_club AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Solo la persona propietaria.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); INSERT INTO public.reader_joint_readings(club_id,title,author,isbn,chapters,goal) VALUES(p_club,b.title,b.author,b.isbn,p_chapters,p_goal) RETURNING id INTO result; RETURN result; END IF; SELECT * INTO STRICT r FROM public.reader_joint_readings WHERE id=p_reading; IF NOT public.reader_club_member(r.club_id,auth.uid()) THEN RAISE EXCEPTION 'No perteneces al club.'; END IF; IF p_action='leave' THEN DELETE FROM public.reader_joint_participants WHERE reading_id=r.id AND user_id=auth.uid(); RETURN r.id; END IF; IF p_action<>'join' THEN RAISE EXCEPTION 'Acción inválida.'; END IF; SELECT * INTO STRICT b FROM public.books WHERE id=p_book AND user_id=auth.uid(); IF public.reader_identity(b.title,b.author)<>public.reader_identity(r.title,r.author) AND (public.reader_isbn(b.isbn)='' OR public.reader_isbn(b.isbn)<>public.reader_isbn(r.isbn)) THEN RAISE EXCEPTION 'Elige una edición de esta lectura.'; END IF; INSERT INTO public.reader_joint_participants(reading_id,user_id,book_id) VALUES(r.id,auth.uid(),b.id) ON CONFLICT(reading_id,user_id) DO UPDATE SET book_id=excluded.book_id; RETURN r.id; END $$;